    def __init__(self, repository):
        self._repo = repository
    # move place, fetch, cancel, close, order_count, orders_for, open_orders, line_count, revenue, tier_summary

class PricingService:
    def __init__(self, tax_rate=0.18, discounts=None):
        self._tax_rate = tax_rate
        self._discounts = discounts or {}
    # move set_discount, discount_for, bulk_discount, set_tax_rate, apply_tax, total_for, policy_rate, is_priced

class AuditService:
    def __init__(self):
        self._audit = []
    # move log, history, last_entry, audit_size, clear_audit

class NotificationService:
    def __init__(self, notifier):
        self._notifier = notifier
        self._sent = 0
    # move notify, sent_count, reset_sent
```

OrderService becomes a thin façade delegating to these services, reducing its own responsibilities.

Create a helper class:

```python
class OrderValidator:
    @staticmethod
    def validate_customer(customer):
        if not isinstance(customer, Customer):
            raise TypeError("customer must be a Customer")

    @staticmethod
    def validate_lines(lines):
        if not lines:
            raise ValueError("an order needs at least one line")
        for line in lines:
            if not isinstance(line, OrderLine):
                raise TypeError("lines must contain OrderLine objects")
            if line.quantity < 0:
                raise ValueError("a line quantity cannot be negative")
            if line.unit_price < 0:
                raise ValueError("a unit price cannot be negative")
```

Move the validation code in `place` to calls to `OrderValidator`.

